#[test]
fn descriptor_rejects_missing_exact_package_resolution_component() {
    let work = tempfile::tempdir().unwrap();
    let put = descriptor_put(work.path());
    let descriptor_cid = put["cid"].as_str().unwrap();
    let component_cid = put["package_resolution_protocol_cid"].as_str().unwrap();
    let store = ObjectStore::open(work.path());
    std::fs::write(store.objects_dir().join(component_cid), b"corrupt").unwrap();
